-- =====================================================================
-- 005  DISCOVERY QUERY LIBRARY
--
-- 8,432 Serper queries generated from
-- BUSINESS MODEL x CATEGORY x PATTERN x PLATFORM x GROWTH x GEOGRAPHY.
--
-- Tiers (stored in discovery_queries.priority):
--   1   2221  platform + category, DTC + category   <- run these first
--   2   2834  business model x category
--   3   2288  growth, directories, alt terminology
--   4   1089  geographic fan-out and broad discovery
--
-- Seeding all of them costs nothing - only EXECUTED queries cost Serper
-- credits. Discovery runs by tier, so start with tier 1.
--
-- GENERATED FILE - do not edit directly.
-- Rebuild: python -m scripts.build_query_library
-- Generated 2026-08-14
-- =====================================================================

-- Tier selection needs this index once the table is large.
create index if not exists idx_discovery_queries_service_priority
  on discovery_queries(service_id, priority, enabled);

-- Negative operators appended to every query at search time, and the
-- business types rejected at classification. Stored in service config so
-- they are tunable without a deploy.
update services
set config = config || jsonb_build_object(
      'query_exclusion_terms', jsonb_build_array(
        '3PL', 'logistics', 'freight', 'courier', 'fulfilment services', 'fulfillment services', 'jobs', 'salary', 'hiring agency'),
      'excluded_business_types', jsonb_build_array(
        '3pl provider', 'third party logistics provider', 'logistics company', 'freight forwarder', 'freight broker', 'courier service', 'shipping company', 'transportation company', 'warehousing company', 'fulfillment provider', 'fulfillment agency', 'marketing agency', 'seo agency', 'web development agency', 'digital agency', 'software company', 'saas platform', 'consulting firm', 'restaurant', 'hotel', 'real estate agency', 'financial services', 'law firm', 'healthcare provider', 'recruitment agency', 'staffing agency'))
where slug = '3pl';


